CREATE FUNCTION platform.is_test_org(p_org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,platform,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM platform.organizations WHERE id=p_org AND is_test AND p_org::text=current_setting('app.organization_id',true) AND platform.has_membership(p_org,false)) $$;
CREATE FUNCTION platform.can_operate_orders(p_org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,platform,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM platform.organization_members WHERE organization_id=p_org AND user_id=platform.current_user_id() AND (role='owner' OR can_manage_orders)) $$;
CREATE FUNCTION platform.create_test_organization(p_id uuid,p_name text,p_timezone text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,platform,pg_temp AS $$ BEGIN PERFORM platform.create_organization(p_id,p_name,p_timezone); UPDATE platform.organizations SET is_test=true WHERE id=p_id; END $$;
