CREATE TABLE platform.conversations(id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES platform.organizations(id),customer_id uuid NOT NULL,created_by uuid NOT NULL REFERENCES platform.users(id),channel text NOT NULL DEFAULT 'internal_chat' CHECK(channel='internal_chat'),is_test boolean NOT NULL DEFAULT true CHECK(is_test),control_mode text NOT NULL DEFAULT 'agent' CHECK(control_mode IN ('agent','human')),status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),in_flight uuid,lease_until timestamptz,message_count integer NOT NULL DEFAULT 0 CHECK(message_count BETWEEN 0 AND 100),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days',UNIQUE(organization_id,id),UNIQUE(organization_id,id,customer_id));
CREATE INDEX conversations_listing ON platform.conversations(organization_id,updated_at DESC,id);
CREATE TABLE platform.messages(id uuid PRIMARY KEY,organization_id uuid NOT NULL,conversation_id uuid NOT NULL,actor_id uuid REFERENCES platform.users(id),role text NOT NULL CHECK(role IN ('customer','assistant','staff','system','tool')),content text NOT NULL CHECK(length(content)<=2000),data jsonb NOT NULL DEFAULT '{}' CHECK(octet_length(data::text)<=32768),client_key uuid NOT NULL,request_hash bytea,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,conversation_id,client_key),FOREIGN KEY(organization_id,conversation_id) REFERENCES platform.conversations(organization_id,id) ON DELETE RESTRICT);
CREATE INDEX messages_history ON platform.messages(organization_id,conversation_id,created_at,id);
CREATE TABLE platform.conversation_events(id uuid PRIMARY KEY,organization_id uuid NOT NULL,conversation_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES platform.users(id),kind text NOT NULL CHECK(kind IN ('created','handoff','resumed','deleted','provider_error','limit')),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,conversation_id) REFERENCES platform.conversations(organization_id,id));
CREATE INDEX conversation_events_history ON platform.conversation_events(organization_id,conversation_id,created_at,id);
CREATE TABLE platform.order_quotes(id uuid PRIMARY KEY,organization_id uuid NOT NULL,conversation_id uuid NOT NULL,customer_id uuid NOT NULL,items jsonb NOT NULL CHECK(jsonb_typeof(items)='array' AND jsonb_array_length(items) BETWEEN 1 AND 10 AND octet_length(items::text)<=32768),created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '5 minutes',agreed_at timestamptz,agreed_by uuid REFERENCES platform.users(id),UNIQUE(organization_id,id),UNIQUE(organization_id,id,conversation_id,customer_id),FOREIGN KEY(organization_id,conversation_id,customer_id) REFERENCES platform.conversations(organization_id,id,customer_id));
CREATE INDEX quotes_conversation ON platform.order_quotes(organization_id,conversation_id,created_at);
CREATE TABLE platform.orders(id uuid PRIMARY KEY,organization_id uuid NOT NULL,conversation_id uuid NOT NULL,customer_id uuid NOT NULL,quote_id uuid NOT NULL,status text NOT NULL DEFAULT 'pending_confirmation' CHECK(status IN ('pending_confirmation','confirmed','rejected','cancelled','completed')),source text NOT NULL DEFAULT 'internal_chat' CHECK(source='internal_chat'),is_test boolean NOT NULL DEFAULT true CHECK(is_test),idempotency_key uuid NOT NULL,total_amount bigint NOT NULL CHECK(total_amount BETWEEN 1 AND 900000000000000),currency_code text NOT NULL DEFAULT 'RUB' CHECK(currency_code='RUB'),version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),confirmed_at timestamptz,confirmed_by uuid REFERENCES platform.users(id),UNIQUE(organization_id,id),UNIQUE(organization_id,quote_id),UNIQUE(organization_id,idempotency_key),FOREIGN KEY(organization_id,quote_id,conversation_id,customer_id) REFERENCES platform.order_quotes(organization_id,id,conversation_id,customer_id));
CREATE INDEX orders_listing ON platform.orders(organization_id,status,created_at DESC,id);
CREATE TABLE platform.order_items(id uuid PRIMARY KEY,organization_id uuid NOT NULL,order_id uuid NOT NULL,variant_id uuid NOT NULL,product_id uuid NOT NULL,quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 10),unit_price_amount bigint NOT NULL CHECK(unit_price_amount BETWEEN 1 AND 9000000000000),currency_code text NOT NULL DEFAULT 'RUB' CHECK(currency_code='RUB'),name_snapshot text NOT NULL CHECK(length(name_snapshot) BETWEEN 1 AND 200),sku_snapshot text NOT NULL CHECK(length(sku_snapshot) BETWEEN 1 AND 64),UNIQUE(organization_id,order_id,variant_id),FOREIGN KEY(organization_id,order_id) REFERENCES platform.orders(organization_id,id),FOREIGN KEY(organization_id,variant_id) REFERENCES platform.product_variants(organization_id,id),FOREIGN KEY(organization_id,product_id) REFERENCES platform.products(organization_id,id));
CREATE INDEX order_items_order ON platform.order_items(organization_id,order_id);
CREATE INDEX order_items_variant ON platform.order_items(organization_id,variant_id);
CREATE TABLE platform.order_events(id uuid PRIMARY KEY,organization_id uuid NOT NULL,order_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES platform.users(id),kind text NOT NULL CHECK(kind IN ('created','confirmed','rejected','cancelled','completed')),reason text NOT NULL DEFAULT '' CHECK(length(reason)<=500),idempotency_key uuid NOT NULL,request_hash bytea NOT NULL CHECK(octet_length(request_hash)=32),result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,order_id,idempotency_key),FOREIGN KEY(organization_id,order_id) REFERENCES platform.orders(organization_id,id));
CREATE INDEX order_events_history ON platform.order_events(organization_id,order_id,created_at,id);
CREATE TABLE platform.ai_usage(organization_id uuid NOT NULL REFERENCES platform.organizations(id),day date NOT NULL DEFAULT current_date,requests integer NOT NULL DEFAULT 0 CHECK(requests>=0),reserved_tokens bigint NOT NULL DEFAULT 0 CHECK(reserved_tokens>=0),used_tokens bigint NOT NULL DEFAULT 0 CHECK(used_tokens>=0),PRIMARY KEY(organization_id,day));
ALTER TABLE platform.inventory_movements ADD COLUMN kind text NOT NULL DEFAULT 'adjust' CHECK(kind IN ('adjust','reserve','release','consume'));
