ALTER TABLE platform.inventory_movements ADD COLUMN reserved_after integer NOT NULL DEFAULT 0 CHECK(reserved_after>=0);
ALTER TABLE platform.inventory_movements ADD COLUMN delta_reserved integer NOT NULL DEFAULT 0 CHECK(delta_reserved=reserved_after-reserved_before);
ALTER TABLE platform.inventory_movements ADD COLUMN order_id uuid;
ALTER TABLE platform.inventory_movements ADD CONSTRAINT movements_reserved CHECK(reserved_before<=quantity_before AND reserved_after<=quantity_after);
ALTER TABLE platform.inventory_movements ADD CONSTRAINT movements_kind CHECK((kind='adjust' AND order_id IS NULL AND delta_reserved=0) OR (kind='reserve' AND order_id IS NOT NULL AND delta=0 AND delta_reserved>0) OR (kind='release' AND order_id IS NOT NULL AND delta=0 AND delta_reserved<0) OR (kind='consume' AND order_id IS NOT NULL AND delta=delta_reserved AND delta<0));
