CREATE FUNCTION platform.lock_order_products(p_ids uuid[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,platform,pg_temp AS $$
DECLARE org uuid; BEGIN
 org:=nullif(current_setting('app.organization_id',true),'')::uuid;
 IF org IS NULL OR NOT platform.is_test_org(org) OR NOT platform.can_operate_orders(org) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF;
 PERFORM id FROM platform.products WHERE organization_id=org AND id=ANY(p_ids) ORDER BY id FOR UPDATE;
END $$;
CREATE FUNCTION platform.list_organization_access() RETURNS TABLE(id uuid,is_test boolean,can_manage_orders boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,platform,pg_temp AS $$ SELECT o.id,o.is_test,(m.role='owner' OR m.can_manage_orders) FROM platform.organizations o JOIN platform.organization_members m ON m.organization_id=o.id WHERE m.user_id=platform.current_user_id() $$;
CREATE FUNCTION platform.set_order_access(p_org uuid,p_user uuid,p_allowed boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,platform,pg_temp AS $$ BEGIN
 IF p_org::text IS DISTINCT FROM current_setting('app.organization_id',true) OR NOT platform.has_membership(p_org,true) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF;
 UPDATE platform.organization_members SET can_manage_orders=p_allowed WHERE organization_id=p_org AND user_id=p_user AND role='member';
 IF NOT FOUND THEN RAISE EXCEPTION 'not found' USING ERRCODE='P0002'; END IF;
END $$;
-- +goose StatementEnd
REVOKE ALL ON FUNCTION platform.lock_order_products(uuid[]),platform.list_organization_access(),platform.set_order_access(uuid,uuid,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION platform.lock_order_products(uuid[]),platform.list_organization_access(),platform.set_order_access(uuid,uuid,boolean) TO aba_app;
